                    const v = k.dv(u8, 0);
                    const e1: u32 = k.a[2];
                    k.wb(e1, v);
                    k.logic(u8, v);
                }
                // $0af6e  rts 
                {
                    k.cy +%= 24;
                    return k.pop32();
                }
            },
            else => return k.bad(pc),
        }
    }

};

